* Libraries for saving data and output;
%let FiguresAddress =..\Data\Fig;
libname data "..\Data"; run;
libname comp "..\Data\Comp"; run;
libname crsp "..\Data\CRSP"; run;
libname ff "..\Data\Fama_French"; run;
* Fama-French Industry classification and winsorizing macros;
%include "macros\winsor.sas";
%include "macros\ind_ff48.sas";

proc sql;
create table comp
	as select c.gvkey, datadate, sic, fyear, oancf, at, act, che, lct, ibc, dlc, 
	abs(prcc_f) as prcc, abs(prcc_f)*csho as mve, dp, ceq, xsga, sale, xad, 
	lt, xrd, capx, txdc, esubc, sppiv, fopo, OIADP, SPI, ib, pi 
	from comp.company as c, comp.funda as f
	where f.gvkey = c.gvkey
    and f.indfmt='INDL' and f.datafmt='STD' and f.popsrc='D' and f.consol='C';  
	quit;

data data.ACC_CFO; 
	set comp12(keep=&winsor_var datadate fyear gvkey loss time high_pti_oi high_intan); 
	run;

/*Merge MISP*/
/*We downloaded MISP measure from http://finance.wharton.upenn.edu/~stambaug/ on May 28, 2021*/
/*The data were available until 2016*/
proc import datafile="..\Data\MISP\Misp_Score.txt" out=mis_price dbms=dlm  replace;  
	getnames=yes; 
	run;

data mis_price2 (keep=permno yyyymm misp); 
	set mis_price (keep=_ var3 var5); 
	permno=_; 
	yyyymm=var3; 
	misp=var5; 
	run;

proc sql; 
	create table sample_misp 
	as select a.*, b.misp 
	from ccm1 a left join mis_price2 b 
	on a.yyyymm=b.yyyymm and a.permno=b.permno; 
	quit;

/*Add CRSP*/
data crsp;
	set crsp.msf;
    if ret in (-44, -55, -66, -77, -88, -99) then delete;  * missing return codes;
	run;

proc sql; 
	create table crsp1
    as select a.*, sum(1,ret)*sum(1,dlret)-1 as adjret /*returns adjusted for delisting*/
	from crsp as a left join crsp.msedelist (where=(missing(dlret)=0)) as b 
	on a.permno=b.permno and intnx('month',a.date,0,'E')=intnx('day',b.DLSTDT,0,'E');
	quit;

/*Merge ccm and crsp*/
proc sql;
	create table ccm_crsp (where =(not missing(adjret)))
    as select intnx('month',date,0,'E') as date format date9., adjret, a.*
	from ccm1 as a left join crsp1 as b 
	on a.permno=b.permno and intnx('month',a.datadate,-12,'E')<b.date<=intnx('month',a.datadate,0,'E');
	quit; 

/*Risk*/
proc sql;
	create table risk (keep=permno fyear risk)
    as select *	, std(adjret) as risk
    from ccm_crsp
    group by permno, fyear
	order by permno, fyear, date;
	quit;

proc sort data=risk nodupkey; 
	by permno fyear; 
	run;

proc sql; 
	create table sample_misp_std 
	as select a.*, b.risk  
	from sample_misp as a left join risk as b 
	on a.permno=b.permno and a.fyear=b.fyear; 
	quit;

/*Alpha as a measure for mispricing*/
proc sql;
	create table ccm_crsp (where =(not missing(adjret)))
    as select intnx('month',date,0,'E') as date format date9., adjret, a.*
	from ccm1 as a left join crsp1 as b 
	on a.permno=b.permno and intnx('month',a.datadate,0,'E')<b.date<=intnx('month',a.datadate,+12,'E');
	quit; 

/*Add factors*/
proc sql;
	create table ret_ff 
    as select a.date, permno, fyear, adjret-rf as ex_ret, mktrf, smb, hml, umd
	from ccm_crsp as a left join ff.Factors_monthly as b 
	on intnx('month',a.date,0,'E')=intnx('month',b.date,0,'E');

/*Save main Stata dataset*/
proc export data=sample_mispricing_risk outfile="..\Data\ACC_CFO.dta" DBMS=STATA replace; 
	run;


	*======================Estimate coefficient on CFO using Annual regressions=============;
proc sort data=data.ACC_CFO out=sample; 
	by fyear; 
	run;

proc reg data=sample outest=coeff_at         noprint; by fyear; model     acc_ave_at   =     cfo_ave_at  /adjrsq; run;
proc reg data=sample outest=coeff_at_mod     noprint; by fyear; model mod_acc_ave_at   = mod_cfo_ave_at  /adjrsq; run;
proc reg data=sample outest=coeff_ceq        noprint; by fyear; model     acc_ave_ceq  =     cfo_ave_ceq /adjrsq; run;
proc reg data=sample outest=coeff_mve        noprint; by fyear; model     acc_ave_mve  =     cfo_ave_mve /adjrsq; run;
proc reg data=sample outest=coeff_mve_mod    noprint; by fyear; model mod_acc_ave_mve  = mod_cfo_ave_mve /adjrsq; run;

data coeff_at      (keep=fyear      cfo_ave_at_b);  set coeff_at;          cfo_ave_at_b  =     cfo_ave_at;  run;
data coeff_at_mod  (keep=fyear  mod_cfo_ave_at_b);  set coeff_at_mod;  mod_cfo_ave_at_b  = mod_cfo_ave_at;  run;
data coeff_ceq     (keep=fyear     cfo_ave_ceq_b); set coeff_ceq;         cfo_ave_ceq_b =     cfo_ave_ceq; run;
data coeff_mve     (keep=fyear     cfo_ave_mve_b); set coeff_mve;         cfo_ave_mve_b =     cfo_ave_mve; run;
data coeff_mve_mod (keep=fyear mod_cfo_ave_mve_b); set coeff_mve_mod; mod_cfo_ave_mve_b = mod_cfo_ave_mve; run;

/*Average/STD for intangibles/capx/leverage*/
proc means data=sample noprint;
	var intangible_ave_at capx_ave_at intangible_ave_mve lev; 
	by fyear; 
	output out=mean_rd 
	mean(intangible_ave_at)=m_intangible_ave_at mean(capx_ave_at)=m_capx_ave_at 
	mean(intangible_ave_mve)=m_intangible_ave_mve 
	std(intangible_ave_at)=std_intangible_ave_at std(lev)=std_lev; 
	run;

/*Merge annual data*/
data data.annual_sample; 
	merge coeff_at coeff_at_mod coeff_ceq coeff_mve coeff_mve_mod mean_rd (drop=_type_ _freq_); 
	by fyear; 
	time=(fyear-1964)/100; 
	run;

proc export data=data.annual_sample outfile="..\Data\Annual_ACC_CFO.dta" DBMS=STATA replace; 
	run;

