ods listing gpath="&FiguresAddress";
options nodate nonumber sysprintfont="Courier";
proc sgplot data=data.annual_sample;
   reg y=cfo_ave_at_b x=fyear/markerattrs=(symbol=circle) LEGENDLABEL="Trend in the coefficient: Replication of Bushman et al. (2016)";
   reg y=mod_cfo_ave_mve_b x=fyear/markerattrs=(symbol=square) LEGENDLABEL="Trend in the coefficient: Numerator and denominator adjustments";
	yaxis 
	label = "Coefficient on CFO"
	values=(-2 -1.5 -1 -0.5 0 0.5)
	labelattrs=(size=15pt weight=bold)
