	xaxis
	labelattrs=( size=16pt weight=bold)
    valueattrs=( size=16pt weight=bold)
	label = "Year";
	keylegend / location=inside position=BOTTOMRIGHT  across=1;
	run;
ods graphics off;

*==================================================================;
*Figure Two;
*===================================================================;
proc sort data=data.ACC_CFO out=weight (keep=fyear intangible_ave_at inverse_at inverse_mve); 
	by fyear intangible_ave_at; 
	run;

proc rank data=weight out=weight ties=low groups=10; 
	var intangible_ave_at; 
	ranks d_intangible_ave_at; 
	by fyear; 
	run;

proc means data=weight noprint; 
	var inverse_at inverse_mve; 
	by fyear d_intangible_ave_at; 
	output out=weight2 
	sum=s_inverse_at s_inverse_mve; 
	run;

proc sql;
    create table weight3
    as select *, sum(s_inverse_at)  as s_s_inverse_at, sum(s_inverse_mve) as s_s_inverse_mve
    from weight2
    group by fyear;
	quit;

/*Weights on high intangible firms*/
data weight4; 
	set weight3;
	if d_intangible_ave_at=9; 
	intan_at = (s_inverse_at /s_s_inverse_at);
	intan_mve= (s_inverse_mve/s_s_inverse_mve );
	run;

	*======================Figure two=============;
ods graphics on / width=6.4in height=2.98in border=off imagename="Fig2" imagefmt=png;
ods listing gpath="&FiguresAddress";
options nodate nonumber sysprintfont="Courier";
proc sgplot data=weight4;
   reg y=intan_at  x=fyear/markerattrs=(symbol=circle) legendlabel="Deflator: Asset";
   reg y=intan_mve x=fyear/markerattrs=(symbol=square) legendlabel="Deflator: MV";
	yaxis 
	label = "Weights on High Intangible Firms"
	labelattrs=(size=15pt weight=bold)
    valueattrs=(size=16pt weight=bold);
	xaxis
	labelattrs=( size=16pt weight=bold)
    valueattrs=( size=16pt weight=bold)
	label = "Year";
	keylegend / location=inside position=BOTTOMRIGHT  across=1;
	run;
ods graphics off;

%let wrds=wrds.wharton.upenn.edu 4016;options comamid=TCP remote=WRDS;
signon username=_prompt_; 

rsubmit; /*Data were downloaded on May 1, 2021*/
proc download data=comp.company out=comp.company; run;
proc download data=comp.funda out=comp.funda; run;
proc download data=crsp.ccmxpf_linktable out=crsp.ccmxpf_linktable; run;
endrsubmit;


rsubmit; /*Data were downloaded on May 28, 2021*/
proc download data=crsp.msf  out=crsp.msf; run;
proc download data=crsp.msedelist out=crsp.msedelist; run;
proc download data=ff.factors_monthly out=ff.factors_monthly; run;
endrsubmit;

/*Alternative intangible investment (investment SG&A) measure following Enache and Srivastava [2018]*/
%ind_ff48 (dset=comp4, outp=invest_sga, sic=sic, bin_var=ff_, ind_code=ff_ind);

data invest_sga2; 
	set invest_sga; 
	main_sga=sum(sga,-rd,-ad);
	main_sga_ave_at=main_sga/ave_at;
	sale_ave_at=sale/ave_at;
	ch_sale=sale-lag_sale;

	if ch_sale<0 then decrease_sale=1; else decrease_sale=0;
	if ib<0 then loss=1; else loss=0;

	if missing(main_sga) then delete;
	if missing(ch_sale) then delete;
	if missing(ib) then delete;
	run; 

proc sort data=invest_sga2; 
	by fyear ff_ind; 
	run;

%winsor(dsetin=invest_sga2, dsetout=invest_sga2, byvar=fyear, vars= main_sga_ave_at sale_ave_at, type=winsor, pctl=1 99);

/*Estimate coefficients used to measure intangible investment (investment SG&A) measure for each industry and year*/
proc reg data=invest_sga2 outest=invest_sga_coeff edf noprint; 
	by fyear ff_ind; 
	model main_sga_ave_at = sale_ave_at decrease_sale loss; 
	run;

/*Alternative intangible investment measure (inv_sga)*/
proc sql;
	create table invest_sga3 (keep=gvkey fyear inv_sga) 
	as select a.*, (a.main_sga_ave_at-b.sale_ave_at*a.sale_ave_at)*a.ave_at as inv_sga
	from invest_sga2 a left join invest_sga_coeff (where =(_EDF_>6)) b
	on a.ff_ind=b.ff_ind and a.fyear=b.fyear;
	quit;

/*rda_5yr is the amortization of R&D capital assuming a 5-year useful life. Other variables are defined similarly.*/
rda_5yr =(1/5) *sum(of rd_lag1-rd_lag5,0);
rda_7yr =(1/7) *sum(of rd_lag1-rd_lag7,0);
rda_10yr=(1/10)*sum(of rd_lag1-rd_lag10,0);

ada_2yr =(1/2) *sum(of ad_lag1-ad_lag2,0);
ada_5yr =(1/5) *sum(of ad_lag1-ad_lag5,0);

sga_a_5yr =(1/5) *sum(of inv_sga_lag1-inv_sga_lag5,0);

rda=rda_5yr;
ada=ada_2yr;

/*rd_asset is R&D capital using a 5-year useful life. Other variables are defined similarly*/
    rd_asset=sum(rd,4/5*rd_lag1,3/5*rd_lag2,2/5*rd_lag3,1/5*rd_lag4,0);
lag_rd_asset=sum(       rd_lag1,4/5*rd_lag2,3/5*rd_lag3,2/5*rd_lag4,1/5*rd_lag5,0);
    ad_asset=sum(ad,1/2*ad_lag1,0);
lag_ad_asset=sum(       ad_lag1,1/2*ad_lag2,0);
    sga_asset=sum(inv_sga,4/5*inv_sga_lag1,3/5*inv_sga_lag2,2/5*inv_sga_lag3,1/5*inv_sga_lag4,0);
lag_sga_asset=sum(            inv_sga_lag1,4/5*inv_sga_lag2,3/5*inv_sga_lag3,2/5*inv_sga_lag4,1/5*inv_sga_lag5,0);

intangible=rd+ad;
alt_intangible=rd+ad+inv_sga;

intangible_amortization=rda+ada;
alt_intangible_amortization=rda+ada+sga_a_5yr;

/*modified ACC and CFO*/
mod_acc=acc-intangible_amortization;
mod_cfo=cfo+intangible;

/*modified BE and alt modified BE*/
ave_ceq_rd=((ceq+rd_asset+ad_asset          )+(lag_ceq+lag_rd_asset+lag_ad_asset              ))/2;
ave_ceq_es=((ceq+rd_asset+ad_asset+sga_asset)+(lag_ceq+lag_rd_asset+lag_ad_asset+lag_sga_asset))/2;

/*Alt modified ACC and CFO*/
es_acc=acc-alt_intangible_amortization;
es_cfo=cfo+alt_intangible;

/*Limit the sample to 1964-2019*/
data comp11;
	set comp10;
	where 1964<=fyear<=2019;
	run;

/*Winsorize continuous variables*/
%let winsor_var=
acc acc_ave_at acc_ave_ceq acc_ave_ceq_es acc_ave_ceq_rd acc_ave_mve acc_beg_mve acc_end_mve adj_10yr_2yr_acc_ave_mve 
adj_10yr_5yr_acc_ave_mve adj_5yr_5yr_acc_ave_mve adj_7yr_2yr_acc_ave_mve adj_7yr_5yr_acc_ave_mve intangible_amortization intangible_amortization_ave_at 
intangible_amortization_ave_mve ave_at ave_mve cfo cfo_ave_at cfo_ave_ceq cfo_ave_ceq_es cfo_ave_ceq_rd cfo_ave_mve cfo_beg_mve cfo_end_mve 
es_acc_ave_at es_acc_ave_mve es_cfo_ave_at es_cfo_ave_ceq_es es_cfo_ave_mve es_ocfo_ave_ceq_es es_ocfo_ave_mve inverse_at inverse_mve 
lag_cfo_ave_at lag_cfo_ave_ceq lag_cfo_ave_mve lag_mod_cfo_ave_at lag_mod_cfo_ave_mve lead_cfo_ave_at lead_cfo_ave_ceq lead_cfo_ave_mve 
lead_mod_cfo_ave_at lead_mod_cfo_ave_mve mod_acc mod_acc_ave_at mod_acc_ave_ceq_es mod_acc_ave_mve mod_acc_beg_mve mod_acc_end_mve 
mod_cfo mod_cfo_ave_at mod_cfo_ave_ceq mod_cfo_ave_ceq_es mod_cfo_ave_ceq_rd mod_cfo_ave_mve mod_cfo_beg_mve 
mod_cfo_end_mve mod_oacc_ave_at mod_oacc_ave_mve mod_ocfo_ave_at mod_ocfo_ave_ceq_es mod_ocfo_ave_mve oacc_ave_at oacc_ave_ceq oacc_ave_mve 
ocfo_ave_at ocfo_ave_ceq ocfo_ave_mve intangible intangible_ave_at intangible_ave_mve si xad xrd capx_ave_at lev;

proc sort data=comp11; 
	by fyear; 
	run;

%winsor(dsetin=comp11,  dsetout=comp12, byvar=fyear, vars= &winsor_var, type=winsor, pctl=1 99);

/*Add CRSP identifiers*/
proc sql;
	create table ccm1 
	as select a.*, b.lpermno as permno
	from sample a left join crsp.ccmxpf_linktable (where=(linktype in ('LU' 'LC') 
	and LINKPRIM in ('P' 'C') and not missing(lpermno))) as b
	on a.gvkey=b.gvkey and (linkdt <= a.datadate) 
	and (a.datadate <= linkenddt or linkenddt= .E);
	quit;

/*Add CRSP*/
data crsp;
	set crsp.msf;
    if ret in (-44, -55, -66, -77, -88, -99) then delete;  * missing return codes;
	run;

proc sql; 
	create table crsp1
    as select a.*, sum(1,ret)*sum(1,dlret)-1 as adjret /*returns adjusted for delisting*/
	from crsp as a left join crsp.msedelist (where=(missing(dlret)=0)) as b 
	on a.permno=b.permno and intnx('month',a.date,0,'E')=intnx('day',b.DLSTDT,0,'E');
	quit;

/*Merge ccm and crsp*/
proc sql;
	create table ccm_crsp (where =(not missing(adjret)))
    as select intnx('month',date,0,'E') as date format date9., adjret, a.*
	from ccm1 as a left join crsp1 as b 
	on a.permno=b.permno and intnx('month',a.datadate,-12,'E')<b.date<=intnx('month',a.datadate,0,'E');
	quit; 

/*Risk*/
proc sql;
	create table risk (keep=permno fyear risk)
    as select *	, std(adjret) as risk
    from ccm_crsp
    group by permno, fyear
	order by permno, fyear, date;
	quit;

proc sort data=risk nodupkey; 
	by permno fyear; 
	run;

proc sql; 
	create table sample_misp_std 
	as select a.*, b.risk  
	from sample_misp as a left join risk as b 
	on a.permno=b.permno and a.fyear=b.fyear; 
	quit;

/*Alpha as a measure for mispricing*/
proc sql;
	create table ccm_crsp (where =(not missing(adjret)))
    as select intnx('month',date,0,'E') as date format date9., adjret, a.*
	from ccm1 as a left join crsp1 as b 
	on a.permno=b.permno and intnx('month',a.datadate,0,'E')<b.date<=intnx('month',a.datadate,+12,'E');
	quit; 

/*Add factors*/
proc sql;
	create table ret_ff 
    as select a.date, permno, fyear, adjret-rf as ex_ret, mktrf, smb, hml, umd
	from ccm_crsp as a left join ff.Factors_monthly as b 
	on intnx('month',a.date,0,'E')=intnx('month',b.date,0,'E');
	quit;

proc sort data=ret_ff; 
	by permno fyear;
	run;

/*Alpha using three- and four-factor models*/
proc reg noprint data=ret_ff outest=three_factor edf; 
	model ex_ret = mktrf smb hml; 
	by permno fyear; 
	run;

proc reg noprint data=ret_ff outest=four_factor edf; 
	model ex_ret = mktrf smb hml umd; 
	by permno fyear; 
 	run;

data three_factor; 
	set three_factor; 
	rename intercept=alpha3; 
	if _edf_>=6; 
	run;

data four_factor; 
	set four_factor; 
	rename intercept=alpha4; 
	if _edf_>=5; 
	run;

/*Merge Alpha*/
proc sql; 
	create table sample_mispricing_risk  
	as select a.*, b.alpha3, c.alpha4
	from sample_misp_std a 
	left join three_factor b on a.fyear=b.fyear and a.permno=b.permno
	left join  four_factor c on a.fyear=c.fyear and a.permno=c.permno; 
	quit;

	*======================Estimate coefficient on CFO using Annual regressions=============;
proc sort data=data.ACC_CFO out=sample; 
	by fyear; 
	run;

proc reg data=sample outest=coeff_at         noprint; by fyear; model     acc_ave_at   =     cfo_ave_at  /adjrsq; run;
proc reg data=sample outest=coeff_at_mod     noprint; by fyear; model mod_acc_ave_at   = mod_cfo_ave_at  /adjrsq; run;
proc reg data=sample outest=coeff_ceq        noprint; by fyear; model     acc_ave_ceq  =     cfo_ave_ceq /adjrsq; run;
proc reg data=sample outest=coeff_mve        noprint; by fyear; model     acc_ave_mve  =     cfo_ave_mve /adjrsq; run;
proc reg data=sample outest=coeff_mve_mod    noprint; by fyear; model mod_acc_ave_mve  = mod_cfo_ave_mve /adjrsq; run;

data coeff_at      (keep=fyear      cfo_ave_at_b);  set coeff_at;          cfo_ave_at_b  =     cfo_ave_at;  run;
data coeff_at_mod  (keep=fyear  mod_cfo_ave_at_b);  set coeff_at_mod;  mod_cfo_ave_at_b  = mod_cfo_ave_at;  run;
data coeff_ceq     (keep=fyear     cfo_ave_ceq_b); set coeff_ceq;         cfo_ave_ceq_b =     cfo_ave_ceq; run;
data coeff_mve     (keep=fyear     cfo_ave_mve_b); set coeff_mve;         cfo_ave_mve_b =     cfo_ave_mve; run;
