/*Average/STD for intangibles/capx/leverage*/
proc means data=sample noprint;
	var intangible_ave_at capx_ave_at intangible_ave_mve lev; 
	by fyear; 
	output out=mean_rd 
	mean(intangible_ave_at)=m_intangible_ave_at mean(capx_ave_at)=m_capx_ave_at 
	mean(intangible_ave_mve)=m_intangible_ave_mve 
	std(intangible_ave_at)=std_intangible_ave_at std(lev)=std_lev; 
	run;

/*Merge annual data*/
data data.annual_sample; 
	merge coeff_at coeff_at_mod coeff_ceq coeff_mve coeff_mve_mod mean_rd (drop=_type_ _freq_); 
	by fyear; 
	time=(fyear-1964)/100; 
	run;

