	by fyear; 
	run;

proc means data=weight noprint; 
	var inverse_at inverse_mve; 
	by fyear d_intangible_ave_at; 
	output out=weight2 
	sum=s_inverse_at s_inverse_mve; 
	run;

proc sql;
    create table weight3
    as select *, sum(s_inverse_at)  as s_s_inverse_at, sum(s_inverse_mve) as s_s_inverse_mve
    from weight2
    group by fyear;
	quit;

/*Weights on high intangible firms*/
data weight4; 
	set weight3;
	if d_intangible_ave_at=9; 
	intan_at = (s_inverse_at /s_s_inverse_at);
	intan_mve= (s_inverse_mve/s_s_inverse_mve );
	run;

