/*Lag and lead CFO for Dechow and Dichev model*/
proc sql;
	create table comp9 
	as select a.*
	, b.cfo_ave_at  as lag_cfo_ave_at  , b.mod_cfo_ave_at  as lag_mod_cfo_ave_at 
	, b.cfo_ave_ceq as lag_cfo_ave_ceq 
	, b.cfo_ave_mve as lag_cfo_ave_mve , b.mod_cfo_ave_mve as lag_mod_cfo_ave_mve
	from comp8 a left join comp8 b 
	on a.gvkey=b.gvkey and a.fyear-1=b.fyear;
	quit;

proc sql;
	create table comp10 
	as select a.*
	, b.cfo_ave_at  as lead_cfo_ave_at , b.mod_cfo_ave_at  as lead_mod_cfo_ave_at 	
	, b.cfo_ave_ceq as lead_cfo_ave_ceq
	, b.cfo_ave_mve as lead_cfo_ave_mve, b.mod_cfo_ave_mve as lead_mod_cfo_ave_mve
	from comp9 a left join comp9 b 
	on a.gvkey=b.gvkey and a.fyear+1=b.fyear; 
	quit;
